import numpy as np

def is_convex_function(f, x_range, n_points=100):
    x_values = np.linspace(x_range[0], x_range[1], n_points)
    hessian_values = []
    for x in x_values:
        h = 1e-5
        f_xx = (f(x + h) - 2*f(x) + f(x - h)) / (h**2)
        hessian_values.append(f_xx)

    is_convex = all(h >= -1e-10 for h in hessian_values)
    return is_convex, np.array(hessian_values)

def check_convexity_multivariable(H):
    eigenvalues = np.linalg.eigvalsh(H)
    return np.all(eigenvalues >= -1e-10)

def f1(x):
    return x**2

def f2(x):
    return -x**2

print(f"f1(x)=x^2 convex: {is_convex_function(f1, (-5, 5))[0]}")
print(f"f2(x)=-x^2 convex: {is_convex_function(f2, (-5, 5))[0]}")
